package ai.taskforge.api;
import ai.taskforge.domain.Document; import ai.taskforge.knowledge.KnowledgeService; import ai.taskforge.repo.DocumentRepository; import ai.taskforge.service.CurrentUser; import org.apache.pdfbox.Loader; import org.apache.pdfbox.text.PDFTextStripper; import org.apache.poi.xwpf.usermodel.XWPFDocument; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.io.*; import java.util.*;
@RestController @RequestMapping("/api/documents") public class DocumentController { private final DocumentRepository docs;private final CurrentUser current;private final KnowledgeService knowledge;public DocumentController(DocumentRepository d,CurrentUser c,KnowledgeService k){docs=d;current=c;knowledge=k;} record View(UUID id,String filename,String type,String status,java.time.Instant uploadedAt){} @GetMapping List<View> list(){return docs.findAll().stream().map(d->new View(d.getId(),d.getFilename(),d.getContentType(),d.getStatus(),d.getUploadedAt())).toList();} @PostMapping(consumes=MediaType.MULTIPART_FORM_DATA_VALUE) View upload(@RequestParam MultipartFile file)throws IOException {if(file.isEmpty()||file.getSize()>15*1024*1024)throw new ApiException("INVALID_FILE","Choose a file up to 15 MB.");String type=Optional.ofNullable(file.getContentType()).orElse("");String name=file.getOriginalFilename()==null?"upload":file.getOriginalFilename();String text=extract(file,type,name);var d=docs.save(new Document(name,type,text,current.get()));knowledge.index(d);return new View(d.getId(),d.getFilename(),d.getContentType(),d.getStatus(),d.getUploadedAt());} private String extract(MultipartFile f,String type,String name)throws IOException {String lower=name.toLowerCase();if(lower.endsWith(".txt")||type.startsWith("text/"))return new String(f.getBytes(),java.nio.charset.StandardCharsets.UTF_8);if(lower.endsWith(".pdf")){try(var p=Loader.loadPDF(f.getBytes())){return new PDFTextStripper().getText(p);}}if(lower.endsWith(".docx")){try(var d=new XWPFDocument(f.getInputStream())){return String.join("\n",d.getParagraphs().stream().map(x->x.getText()).toList());}}throw new ApiException("UNSUPPORTED_FILE","Only PDF, DOCX, and TXT files are supported.");} }
